// spec: .qa/e2e/specs/content-filter.md 1.3 · тикет #2ee07c55 (AC 2, 5, 6)
// Две роли: admin добавляет слово «qaauto<буквы>» в «מילים אסורות» → user4 публикует пост с ним → пост в «לבדיקה»
// с «מילה אסורה «<слово>»» → admin удаляет слово (×) → слова нет в списке.
// @data: в finally — удаление слова (если осталось) и поста.
// Известно (программист 10.11): слово с приклеенной служебной буквой («בוואטסאפ») не ловится — не проверяем.
import { test, expect } from '@playwright/test';
import type { Page } from '@playwright/test';
import { ADMIN_URL, adminAs, appApi, cId, closeAdmin, closeApp, contentDetail, contentQueue, createPost, deletePost, iphoneAs, openBannedWords, openContent, removeBannedWord, tag } from '../moderation-menu/mod-helpers';
import type { Api } from '../_shared/api';

test.describe('סינון תוכן אוטומטי בסיסי', () => {
  test('Список «מילים אסורות»: добавленное слово помечает пост, удаление слова (×) убирает его из списка @desktop @data (#2ee07c55)', async ({ browser }) => {
    test.setTimeout(150_000);
    const admin = await adminAs(browser);
    let user: Page | undefined;
    let api: Api | undefined;
    let id = '';
    let wordAdded = false;
    const word = `qaauto${tag(6)}`;
    const text = `QA-AUTO 2ee07c55 ${tag(4)} ${word}`;
    try {
      // Добавить слово (AC 6)
      await openContent(admin);
      const countBefore = Number(((await admin.getByRole('button', { name: /^מילים אסורות/ }).textContent()) ?? '').match(/\d+/)?.[0] ?? 'NaN');
      const dlg = await openBannedWords(admin);
      await expect(dlg).toContainText('התוכן נשאר גלוי עד להחלטה');
      const input = dlg.getByRole('textbox', { name: 'מילה חדשה' });
      await input.fill(word);
      const added = admin.waitForResponse((r) => r.request().method() === 'POST' && new URL(r.url()).pathname === '/content');
      await input.press('Enter');
      expect((await added).ok(), 'server action добавления слова').toBeTruthy();
      wordAdded = true;
      const list = dlg.getByRole('list', { name: 'הרשימה' });
      await expect(list.getByRole('listitem').filter({ hasText: word })).toHaveCount(1);
      await expect(list.getByRole('button', { name: `הסרת ${word}` })).toBeVisible();
      await dlg.getByRole('button', { name: 'סגירה' }).click();
      if (!Number.isNaN(countBefore)) await expect(admin.getByRole('button', { name: /^מילים אסורות/ })).toHaveText(new RegExp(`${countBefore + 1}`));

      // Пост с этим словом помечается (AC 2, 5)
      user = await iphoneAs(browser, 'user4');
      api = await appApi(user);
      id = await createPost(api, text);
      await admin.goto(`${ADMIN_URL}/content?tab=review`);
      const row = contentQueue(admin).getByRole('link', { name: new RegExp(cId(id)) });
      await expect(row).toContainText(text);
      await row.click();
      await expect(contentDetail(admin).getByRole('listitem').filter({ hasText: 'סינון אוטומטי:' })).toContainText(`סינון אוטומטי: מילה אסורה «${word}»`);

      // Удалить слово (×)
      await openContent(admin);
      const dlg2 = await openBannedWords(admin);
      const removed = admin.waitForResponse((r) => r.request().method() === 'POST' && new URL(r.url()).pathname === '/content');
      await dlg2.getByRole('button', { name: `הסרת ${word}` }).click();
      expect((await removed).ok(), 'server action удаления слова').toBeTruthy();
      await expect(dlg2.getByRole('list', { name: 'הרשימה' }).getByRole('listitem').filter({ hasText: word })).toHaveCount(0);
      wordAdded = false;

      await deletePost(api, id);
      id = '';
    } finally {
      if (wordAdded) await removeBannedWord(admin, word).catch(() => undefined);
      if (api && id) await deletePost(api, id);
      await closeApp(user, 'user4');
      await closeAdmin(admin);
    }
  });
});
